#include "numerics.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <thread>
#include <mutex>
#include <atomic>
using namespace hour_local;
struct Job{int N,budget;std::string scenario,initialization,id;};
int main(int argc,char**argv){try{std::filesystem::path out=argc>1?argv[1]:"results";std::filesystem::create_directories(out/"warm_traces");std::vector<Job>jobs;for(int N:{8,32})for(std::string scenario:{"nominal","mass10"})for(int budget:{512,2048})for(std::string initialization:{"cold","warm","joint_bootstrap"})jobs.push_back({N,budget,scenario,initialization,"warm_"+std::to_string(jobs.size())});
 std::ofstream csv(out/"warm_block_dynamics.csv"),steps(out/"warm_block_steps.csv");csv<<std::setprecision(16)<<"id,N,scenario,initialization,budget,rho,partition,h,requested_steps,completed_steps,inexact_steps,max_primal,max_stationarity,max_energy_error,rms_position,mean_evaluations,compute_ms,status\n";steps<<std::setprecision(16)<<"id,step,solver,converged,primal,stationarity,evaluations,visits,dual_sweeps\n";std::mutex mutex;std::atomic<int>next{0};std::vector<std::thread>threads;
 for(int t=0;t<4;++t)threads.emplace_back([&](){for(;;){int index=next.fetch_add(1);if(index>=int(jobs.size()))break;const auto&j=jobs[index];auto c=chain_case(j.N,1,j.scenario=="mass10"?10:1);const auto&m=c.model;State s=c.initial,reference=s;V dual;double E0=energy(m,s),E=E0-minimum_energy(m),h=1./60,maxP=0,maxS=0,maxE=0,error=0,ms=0;int bad=0,completed=0,evals=0;std::string status="completed";
   std::ofstream trace(out/"warm_traces"/(j.id+".csv"));trace<<std::setprecision(16)<<"time,energy,reference_energy";for(int k=0;k<dof(m);++k)trace<<",x"<<k<<",v"<<k<<",ref_x"<<k<<",ref_v"<<k;trace<<'\n';auto writerow=[&](double time){trace<<time<<','<<energy(m,s)<<','<<energy(m,reference);for(int k=0;k<dof(m);++k)trace<<','<<s.x[k]<<','<<s.v[k]<<','<<reference.x[k]<<','<<reference.v[k];trace<<'\n';};writerow(0);
   for(int step=0;step<8;++step){Problem p(m,s,h,E);Options o;o.solver="AL";o.initial="midpoint";o.partition="edge_full";o.stable=true;o.rho=100;o.budget=j.budget;if(j.initialization=="joint_bootstrap"&&step==0){o.solver="kkt";o.budget=64;}auto r=solve(p,o,j.initialization!="cold"&&dual.size()?&dual:nullptr);State current=p.state(r.z),refnext=reference_step(m,reference,h,64);if(!r.converged)++bad;maxP=std::max(maxP,r.primal);maxS=std::max(maxS,r.dual_residual);evals+=r.evaluations;ms+=r.milliseconds;if(!finite(current)){status="nonfinite";break;}maxE=std::max(maxE,std::abs(energy(m,current)-E0)/E);error+=(current.x-refnext.x).squaredNorm()/m.count;s=current;reference=refnext;dual=r.dual;++completed;writerow(step*h+h);std::ostringstream row;row<<std::setprecision(16)<<j.id<<','<<step<<','<<o.solver<<','<<r.converged<<','<<r.primal<<','<<r.dual_residual<<','<<r.evaluations<<','<<r.visits<<','<<r.sweeps<<'\n';std::lock_guard<std::mutex>lock(mutex);steps<<row.str();}
   if(status=="completed"&&bad)status="completed_inexact";std::ostringstream row;row<<std::setprecision(16)<<j.id<<','<<j.N<<','<<j.scenario<<','<<j.initialization<<','<<j.budget<<",100,edge_full,"<<h<<",8,"<<completed<<','<<bad<<','<<maxP<<','<<maxS<<','<<maxE<<','<<std::sqrt(error/std::max(1,completed))<<','<<double(evals)/std::max(1,completed)<<','<<ms<<','<<status<<'\n';std::lock_guard<std::mutex>lock(mutex);csv<<row.str();csv.flush();steps.flush();std::cout<<j.id<<' '<<j.N<<' '<<j.initialization<<" bad="<<bad<<'\n';}});for(auto&t:threads)t.join();return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
